import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction

UNIT_KG = {
    "kg": Fraction(1),
    "g": Fraction(1, 1000),
    "lb": Fraction(45359237, 100000000),
    "oz": Fraction(28349523125, 1000000000000),
}
PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}
COLUMNS = {
    "east": ["id", "type", "shipped", "gross", "net", "status", "note"],
    "harbor": ["rec", "ref", "date", "weight", "state"],
    "lakeside": ["id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"],
    "river": ["t", "ref", "shipped", "weight", "status"],
    "west": ["id", "typ", "shipped", "weight", "status", "note"],
}
DELIM = {"east": ",", "harbor": "|", "lakeside": ",", "river": "\t", "west": ";"}
HARBOR_STATUS = {"dlv": "delivered", "dll": "delivered_late", "can": "cancelled",
                 "ret": "returned", "hld": "held"}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
             "R": "returned", "H": "held"}
FW_LAYOUTS = {
    "FW1": dict(length=42, type=(9, 10), id=(0, 9), shipped=(10, 17), weight=(17, 25),
                status=(25, 26), date="ydoy", unit="g", scale=Fraction(1)),
    "FW2": dict(length=43, type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26),
                status=(26, 27), date="ymd", unit="kg", scale=Fraction(1, 100)),
    "FW3": dict(length=41, type=(16, 17), id=(0, 9), shipped=(9, 16), weight=(17, 24),
                status=(24, 25), date="ydoy", unit="lb", scale=Fraction(1, 10)),
}


def read_bytes(path):
    with open(path, "rb") as handle:
        data = handle.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data


def decode(data):
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8")
    if data[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return data.decode("utf-16")
    head = data[:2000].decode("latin-1")
    match = re.search(r"^#\s*charset\s*:\s*([\w.\-]+)", head, re.M | re.I)
    if match:
        return data.decode(match.group(1).strip())
    return data.decode("utf-8")


def sh_number(text):
    match = re.match(r"^\s*sh\D*?(\d+)\s*$", text or "", re.I)
    return int(match.group(1)) if match else None


def norm_status(text):
    return re.sub(r"[\s\-]+", "_", (text or "").strip().lower())


def rtype(text):
    low = (text or "").strip().lower()
    if low.startswith("v"):
        return "void"
    if low.startswith("c") or low.startswith("a"):
        return "correction"
    return "new"


def parse_number(text, decimal_comma=False):
    text = text.strip()
    if decimal_comma:
        text = text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", "")
    return Fraction(Decimal(text))


def split_unit(text):
    match = re.match(r"^\s*([-+0-9.,]+)\s*([A-Za-z]+)\s*$", text)
    if match and match.group(2).lower() in UNIT_KG:
        return match.group(1), match.group(2).lower()
    return text, None


def to_utc_date(value, form):
    value = (value or "").strip()
    if not value:
        return None
    if re.match(r"^\d{4}-\d\d-\d\d[T ]\d", value):
        parsed = datetime.fromisoformat(value.replace(" ", "T", 1))
        if parsed.tzinfo is not None:
            parsed = parsed.astimezone(timezone.utc)
        return parsed.date()
    form = (form or "iso").strip()
    upper = form.upper()
    if upper == "SERIAL":
        return date(1899, 12, 30) + timedelta(days=int(float(value)))
    match = re.match(r"^(\d{1,2}) ([A-Za-z]{3})[A-Za-z]* (\d{4})$", value)
    if match:
        return date(int(match.group(3)), MONTHS[match.group(2).lower()], int(match.group(1)))
    parts = [int(part) for part in re.split(r"[-/.]", value)]
    if upper in ("ISO", "YMD", "YYYY-MM-DD", "YYYYMMDD") or parts[0] > 31:
        return date(parts[0], parts[1], parts[2])
    if upper in ("DMY", "DD/MM/YYYY", "DD-MM-YYYY", "DD.MM.YYYY"):
        return date(parts[2], parts[1], parts[0])
    if upper in ("MM/DD/YYYY", "MDY"):
        return date(parts[2], parts[0], parts[1])
    return date(parts[2], parts[1], parts[0])


def make_record(kind, number, ship_date, weight_kg, status):
    return {"kind": kind, "number": number, "date": ship_date, "kg": weight_kg,
            "status": norm_status(status)}


def physical_rows(text, quoting):
    lines = text.split("\n")
    index = 0
    while index < len(lines):
        line = lines[index].rstrip("\r")
        index += 1
        if line.startswith("#") or not line.strip():
            yield ("comment" if line.startswith("#") else "blank"), line
            continue
        if quoting:
            while line.count('"') % 2 == 1 and index < len(lines):
                line += "\n" + lines[index].rstrip("\r")
                index += 1
        yield "row", line


def split_row(line, delimiter, quoting):
    if not quoting:
        return line.split(delimiter)
    fields, current, inside, pos = [], [], False, 0
    while pos < len(line):
        char = line[pos]
        if inside:
            if char == '"':
                if line[pos + 1:pos + 2] == '"':
                    current.append('"')
                    pos += 1
                else:
                    inside = False
            else:
                current.append(char)
        elif char == '"':
            inside = True
        elif char == delimiter:
            fields.append("".join(current))
            current = []
        else:
            current.append(char)
        pos += 1
    fields.append("".join(current))
    return fields


def parse_delimited(depot, text):
    delimiter = DELIM[depot]
    quoting = delimiter == ","
    known = set(COLUMNS[depot])
    directives = {}
    seq = None
    header = None
    records = []
    for what, line in physical_rows(text, quoting):
        if what == "blank":
            continue
        if what == "comment":
            match = re.match(r"^#\s*([^:=]+?)\s*:\s*(.*?)\s*$", line)
            if match:
                directives[match.group(1).lower()] = match.group(2)
                if match.group(1).lower() == "seq" and seq is None:
                    seq = int(match.group(2))
            else:
                match = re.match(r"^#.*\bseq\s*=\s*(\d+)", line)
                if match and seq is None:
                    seq = int(match.group(1))
            continue
        fields = split_row(line, delimiter, quoting)
        names = [field.strip().lower() for field in fields]
        if names and all(name in known for name in names):
            header = names
            continue
        if header is None:
            continue
        weight_name = {"east": "gross", "lakeside": "gross_kg"}.get(depot, "weight")
        if len(fields) > len(header):
            widx = header.index(weight_name)
            if widx + 1 < len(fields) and fields[widx + 1].strip().lower() in UNIT_KG:
                row_unit = fields.pop(widx + 1).strip().lower()
            else:
                row_unit = None
                for pos, field in enumerate(fields):
                    if field.strip().lower() in UNIT_KG:
                        row_unit = fields.pop(pos).strip().lower()
                        break
        else:
            row_unit = None
        fields = fields + [""] * (len(header) - len(fields))
        row = dict(zip(header, fields))
        record = delimited_record(depot, row, row_unit, directives)
        if record:
            records.append(record)
    return seq, records


def directive_unit(directives):
    for key in ("unit", "weight unit"):
        if key in directives:
            word = directives[key].split()[0].lower() if directives[key].split() else ""
            if word in UNIT_KG:
                return word
    return None


def delimited_record(depot, row, row_unit, directives):
    id_col = {"harbor": "ref", "river": "ref"}.get(depot, "id")
    number = sh_number(row.get(id_col, ""))
    if number is None:
        return None
    kind_col = {"east": "type", "harbor": "rec", "lakeside": "kind",
                "river": "t", "west": "typ"}[depot]
    kind = rtype(row.get(kind_col, ""))
    if kind == "void":
        return make_record(kind, number, None, None, "")
    form = directives.get("dates") or directives.get("date format")
    if depot == "west":
        form = "DD.MM.YYYY"
    elif depot == "harbor" and not form:
        form = "iso"
    date_col = {"harbor": "date"}.get(depot, "shipped")
    ship_date = to_utc_date(row.get(date_col, ""), form)
    weight_col = {"east": "gross", "lakeside": "gross_kg"}.get(depot, "weight")
    raw = row.get(weight_col, "")
    raw, suffix = split_unit(raw)
    if suffix:
        unit = suffix
    elif row_unit:
        unit = row_unit
    elif depot == "lakeside":
        unit = "kg"
    else:
        unit = directive_unit(directives) or "kg"
    kg = parse_number(raw, depot == "west") * UNIT_KG[unit]
    status = row.get("state") if depot == "harbor" else row.get("status")
    if depot == "harbor":
        status = HARBOR_STATUS.get((status or "").strip().lower(), status)
    return make_record(kind, number, ship_date, kg, status)


def parse_fixed(text):
    seq = None
    layout = None
    records = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        if line.startswith("#"):
            match = re.match(r"^#LAYOUT\s+(\S+)", line)
            if match:
                layout = match.group(1).upper()
            match = re.match(r"^#SEQ\s+(\d+)", line)
            if match and seq is None:
                seq = int(match.group(1))
            continue
        if "\x0c" in line or "SHIPMENT LISTING" in line:
            continue
        name = None
        for candidate, spec in FW_LAYOUTS.items():
            if len(line) == spec["length"]:
                name = candidate
        if name is None and layout in FW_LAYOUTS:
            spec = FW_LAYOUTS[layout]
            if spec["status"][1] <= len(line) < spec["length"]:
                name = layout
                line = line.ljust(spec["length"])
        if name is None:
            continue
        spec = FW_LAYOUTS[name]
        number = sh_number(line[slice(*spec["id"])])
        if number is None:
            continue
        kind = rtype(line[slice(*spec["type"])])
        if kind == "void":
            records.append(make_record(kind, number, None, None, ""))
            continue
        raw_date = line[slice(*spec["shipped"])]
        if spec["date"] == "ydoy":
            ship_date = date(int(raw_date[:4]), 1, 1) + timedelta(days=int(raw_date[4:]) - 1)
        else:
            ship_date = date(int(raw_date[:4]), int(raw_date[4:6]), int(raw_date[6:8]))
        kg = int(line[slice(*spec["weight"])]) * spec["scale"] * UNIT_KG[spec["unit"]]
        status = FW_STATUS.get(line[slice(*spec["status"])].strip().upper(), "")
        records.append(make_record(kind, number, ship_date, kg, status))
    return seq, records


def parse_json(text):
    seq = None
    records = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        value = json.loads(line)
        objects = value if isinstance(value, list) else [value]
        for obj in objects:
            if not isinstance(obj, dict):
                continue
            if "meta" in obj and "id" not in obj:
                if seq is None and "seq" in obj["meta"]:
                    seq = int(obj["meta"]["seq"])
                continue
            number = sh_number(str(obj.get("id", "")))
            if number is None:
                continue
            kind = rtype(obj.get("kind", ""))
            if kind == "void":
                records.append(make_record(kind, number, None, None, ""))
                continue
            kg = None
            for key, raw in obj.items():
                if key.lower().startswith("weight_") and key[7:].lower() in UNIT_KG:
                    kg = parse_number(str(raw)) * UNIT_KG[key[7:].lower()]
            if kg is None and "weight" in obj:
                raw, suffix = split_unit(str(obj["weight"]))
                unit = suffix or str(obj.get("unit", "kg")).lower()
                kg = parse_number(raw) * UNIT_KG[unit]
            ship_date = to_utc_date(str(obj.get("shipped_at", "")), "iso")
            records.append(make_record(kind, number, ship_date, kg, obj.get("status", "")))
    return seq, records


def parse_xml(data):
    root = ET.fromstring(data)
    seq = int(root.get("seq")) if root.get("seq") else None
    root_unit = (root.get("weight-unit") or "kg").strip().lower()
    records = []
    for element in root.iter("shipment"):
        number = sh_number(element.get("id", ""))
        if number is None:
            continue
        kind = rtype(element.get("type", ""))
        if kind == "void":
            records.append(make_record(kind, number, None, None, ""))
            continue
        shipped = element.get("shipped")
        child = element.find("shipped")
        if child is not None and (child.text or "").strip():
            shipped = child.text
        ship_date = to_utc_date(shipped, "iso")
        weight = element.find("weight")
        raw, suffix = split_unit(weight.text or "")
        unit = (weight.get("unit") or suffix or element.get("weight-unit") or root_unit).strip().lower()
        kg = parse_number(raw) * UNIT_KG[unit]
        status = element.find("status")
        records.append(make_record(kind, number, ship_date, kg,
                                   status.text if status is not None else ""))
    return seq, records


def parse_file(depot, path):
    data = read_bytes(path)
    stripped = data.lstrip(b"\xef\xbb\xbf")
    if stripped[:5] == b"<?xml" or stripped[:7] == b"<export":
        return parse_xml(data)
    text = decode(data)
    if depot in COLUMNS:
        return parse_delimited(depot, text)
    first = text.lstrip("\ufeff").lstrip()[:1]
    if first == "{" or first == "[":
        return parse_json(text)
    return parse_fixed(text)


def quantize(value):
    return float(Decimal(value.numerator).__truediv__(Decimal(value.denominator)).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP)) if False else float(
        (Decimal(value.numerator) / Decimal(value.denominator)).quantize(
            Decimal("0.01"), rounding=ROUND_HALF_UP))


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0]
        seq, records = parse_file(depot, path)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, records))

    corrections = resends = 0
    current_by_depot = {}
    for depot, files in exports.items():
        current = {}
        for _, _, records in sorted(files, key=lambda item: (item[0], item[1])):
            for record in records:
                number = record["number"]
                if record["kind"] == "new":
                    if number in current:
                        resends += 1
                    else:
                        current[number] = record
                elif record["kind"] == "correction":
                    current[number] = record
                    corrections += 1
                else:
                    current.pop(number, None)
                    corrections += 1
        current_by_depot[depot] = current

    def rank(depot):
        return PRIORITY.index(depot) if depot in PRIORITY else len(PRIORITY)

    owners = {}
    for depot in sorted(current_by_depot, key=lambda d: (rank(d), d)):
        for number in current_by_depot[depot]:
            owners.setdefault(number, []).append(depot)

    depots = {depot: [0, Fraction(0)] for depot in sorted(exports)}
    months = {}
    handovers = 0
    for number, holders in owners.items():
        if len(holders) > 1:
            handovers += 1
        depot = holders[0]
        record = current_by_depot[depot][number]
        if record["status"] not in ("delivered", "delivered_late"):
            continue
        depots[depot][0] += 1
        depots[depot][1] += record["kg"]
        key = "%04d-%02d" % (record["date"].year, record["date"].month)
        entry = months.setdefault(key, [0, Fraction(0)])
        entry[0] += 1
        entry[1] += record["kg"]

    result = {
        "depots": {d: {"shipments": v[0], "total_kg": quantize(v[1])} for d, v in depots.items()},
        "months": {m: {"shipments": months[m][0], "total_kg": quantize(months[m][1])}
                   for m in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as handle:
        json.dump(result, handle, indent=2)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
